        row = []
        for c in range(0, m, 3):
            block = [grid[i][j] for i in range(r, min(r + 3, n))
                     for j in range(c, min(c + 3, m))]
            counts = {}
            for v in block:
                counts[v] = counts.get(v, 0) + 1
            bg = min(counts, key=lambda v: counts[v])
            candidates = [v for v in counts if v != bg]
            if not candidates:
                row.append(bg)
            else:
                row.append(max(candidates, key=lambda v: (counts[v], -block.index(v))))
        out.append(row)
    return out
