                     for j in range(c, min(c + 3, len(grid[0])))]
            # 5 is the speckle/noise color; the remaining color carries
            # the value represented by this 3x3 patch.
            values = [v for v in block if v != 5]
            if values:
                row.append(max(set(values), key=values.count))
            else:
                row.append(5)
        out.append(row)
    return out
